import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design tokens
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ========== Textured Plane (Sprite Base) ==========

  // Atlas aspect ratio: 512 / 320 = 1.6
  const atlasAspectRatio = 512 / 320;

  // Plane geometry sized to atlas aspect ratio
  const planeWidth = 1.4;
  const planeHeight = planeWidth / atlasAspectRatio;
  const planeGeometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load ceramic grain texture via cached loader
  const textureMap = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create material using TSL texture node
  const textureNode = texture(textureMap);
  const material = new MeshBasicNodeMaterial({
    colorNode: textureNode,
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(planeGeometry, material);

  // Apply scene placement from config
  const position = config.position || [0, 0, 0];
  const rotation = config.rotation || [0, 0, 0];
  const scale = config.scale || [1, 1, 1];

  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  group.add(mesh);

  // ========== Text Overlay ==========

  if (config.textContent) {
    const textObject = ctx.fontAtlas.render({
      text: config.textContent,
      size: 0.2,
      weight: 400,
      family: 'Lora',
      color: colors.ink,
      align: 'center',
    });

    textObject.position.z = 0.01;
    group.add(textObject);
  }

  // ========== Event Handlers & Cleanup ==========

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
    textureMap.dispose();
    gsap.killTweensOf(group);
    gsap.killTweensOf(mesh);
  };

  return group;
}
